//! The Burrito NG wrapper: a self-extracting launcher for a Mix release.
//!
//! On first run (or every run, for debug builds) the embedded payload (an xz compressed tar) is
//! unpacked into a per-version install directory. The Erlang VM is then launched from there.

mod launcher;
mod logger;
mod maintenance;
mod metadata;
// `payload::pack` is only used by build.rs.
#[allow(dead_code)]
mod payload;

/// Generated by `build.rs`: `RELEASE_NAME`, `IS_PROD`, `MUSL_RUNTIME_PATH`.
#[allow(dead_code)]
mod config {
    include!(concat!(env!("OUT_DIR"), "/config.rs"));
}

/// The user's plugin (or a no-op), copied into place by `build.rs`.
mod plugin {
    include!(concat!(env!("OUT_DIR"), "/plugin.rs"));
}

use std::ffi::OsString;
use std::fs;
use std::io::{self, IsTerminal};
use std::path::{Path, PathBuf};

use logger::{debug, err, info};
use metadata::Metadata;

const INSTALL_SUFFIX: &str = ".burrito_ng";

pub const PAYLOAD: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/payload.tar.xz"));
pub const RELEASE_METADATA_JSON: &str = include_str!(concat!(env!("OUT_DIR"), "/_metadata.json"));

fn main() {
    let code = match run() {
        Ok(code) => code,
        Err(e) => {
            err!("{e}");
            1
        }
    };
    std::process::exit(code);
}

fn run() -> io::Result<i32> {
    if cfg!(burrito_ng_stub) {
        err!("This wrapper was built without a payload (__BURRITO_NG_RELEASE_PATH was not set).");
        return Ok(1);
    }

    // Everything after argv[0] is passed to Erlang.
    let args: Vec<OsString> = std::env::args_os().skip(1).collect();

    // If on Linux, maybe install the musl libc runtime for our pre-compiled Erlang.
    #[cfg(target_os = "linux")]
    maybe_install_musl_runtime();

    let self_path = std::env::current_exe()?;

    // Non-production builds always do a clean install.
    let wants_clean_install = !config::IS_PROD;

    let meta = Metadata::parse(RELEASE_METADATA_JSON)
        .map_err(|e| io::Error::other(format!("failed to parse embedded metadata: {e}")))?;
    let base_install_dir = base_install_dir();
    let install_dir = install_dir(&base_install_dir, &meta);
    let metadata_path = install_dir.join("_metadata.json");

    // Maintenance commands
    if args.first().is_some_and(|a| a == "maintenance") {
        let maint_args: Vec<String> = args[1..]
            .iter()
            .map(|a| a.to_string_lossy().into_owned())
            .collect();
        maintenance::run(&maint_args, &install_dir, RELEASE_METADATA_JSON)?;
        return Ok(0);
    }

    debug!("Size of embedded payload is: {}", PAYLOAD.len());
    debug!("Install Directory: {}", install_dir.display());
    debug!("Metadata path: {}", metadata_path.display());

    fs::create_dir_all(&install_dir)?;

    // If the metadata file exists, the payload is already installed.
    let needs_install = match fs::metadata(&metadata_path) {
        Ok(_) => false,
        Err(e) if e.kind() == io::ErrorKind::NotFound => true,
        Err(e) => {
            err!("We failed to open the destination directory with an unexpected error: {e}");
            return Ok(1);
        }
    };

    debug!("Passing args: {args:?}");

    plugin::burrito_ng_plugin_entry(&install_dir.to_string_lossy(), RELEASE_METADATA_JSON);

    if needs_install || wants_clean_install {
        // When re-installing over an existing install (debug builds), delete it first to
        // prevent a macOS SIP issue when "replacing" a Mach-O in place.
        if wants_clean_install && !needs_install {
            fs::remove_dir_all(&install_dir)?;
            fs::create_dir_all(&install_dir)?;
        }

        install_payload(&install_dir, &metadata_path)?;
    } else {
        debug!("Skipping archive unpacking, this machine already has the app installed!");
    }

    maintenance::clean_old_versions(&base_install_dir, &install_dir)?;

    let is_tty = io::stdout().is_terminal();
    launcher::launch(&install_dir, &meta, &self_path, &args, is_tty)
}

fn install_payload(install_dir: &Path, metadata_path: &Path) -> io::Result<()> {
    payload::unpack(PAYLOAD, install_dir)
        .map_err(|e| io::Error::new(e.kind(), format!("failed to unpack payload: {e}")))?;
    debug!("Unpacked payload into {}", install_dir.display());

    // The metadata file is written last: its presence marks a complete install.
    fs::write(metadata_path, RELEASE_METADATA_JSON)
}

fn install_dir_env_name() -> String {
    format!("{}_INSTALL_DIR", config::RELEASE_NAME.to_ascii_uppercase())
}

/// The base directory all versions of this app are installed into. Uses the
/// `<RELEASE_NAME>_INSTALL_DIR` override when present. Exits on failure.
fn base_install_dir() -> PathBuf {
    let env_name = install_dir_env_name();

    let base = match std::env::var_os(&env_name).filter(|v| !v.is_empty()) {
        Some(path) => {
            info!("Install path is being overridden using `{env_name}`");
            info!("New install path is: {}", path.to_string_lossy());
            Some(PathBuf::from(path).join(INSTALL_SUFFIX))
        }
        None => app_data_dir().map(|dir| dir.join(INSTALL_SUFFIX)),
    };

    match base {
        Some(base) if fs::create_dir_all(&base).is_ok() => base,
        _ => install_dir_error(),
    }
}

fn install_dir(base_install_dir: &Path, meta: &Metadata) -> PathBuf {
    base_install_dir.join(format!(
        "{}_erts-{}_{}",
        config::RELEASE_NAME,
        meta.erts_version,
        meta.app_version
    ))
}

fn env_path(name: &str) -> Option<PathBuf> {
    std::env::var_os(name)
        .filter(|v| !v.is_empty())
        .map(PathBuf::from)
}

#[cfg(windows)]
fn app_data_dir() -> Option<PathBuf> {
    env_path("APPDATA")
}

#[cfg(target_os = "macos")]
fn app_data_dir() -> Option<PathBuf> {
    env_path("HOME").map(|home| home.join("Library").join("Application Support"))
}

#[cfg(not(any(windows, target_os = "macos")))]
fn app_data_dir() -> Option<PathBuf> {
    env_path("XDG_DATA_HOME").or_else(|| env_path("HOME").map(|home| home.join(".local/share")))
}

fn install_dir_error() -> ! {
    let env_name = install_dir_env_name();
    err!("We could not install this application to the default directory.");
    err!("This may be due to a permission error.");
    err!(
        "Please override the default {} install directory using the `{env_name}` environment variable.",
        config::RELEASE_NAME
    );
    err!("On Linux or MacOS you can run the command: `export {env_name}=/some/other/path`");
    err!("On Windows you can use: `SET {env_name}=D:\\some\\other\\path`");
    std::process::exit(1);
}

#[cfg(target_os = "linux")]
fn maybe_install_musl_runtime() {
    use std::io::Write;
    use std::os::unix::fs::PermissionsExt;

    const MUSL_RUNTIME_BYTES: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/musl-runtime.so"));

    let target = config::MUSL_RUNTIME_PATH;
    if target.is_empty() || MUSL_RUNTIME_BYTES.is_empty() {
        return;
    }

    if Path::new(target).exists() {
        debug!("The musl runtime file is already present. Continuing.");
        return;
    }

    // Write to a temporary file and rename it into place, so a concurrently starting
    // instance never sees a partially written library.
    let tmp = format!("{target}.{}.tmp", std::process::id());
    let result = (|| -> io::Result<()> {
        let mut file = fs::File::create(&tmp)?;
        file.write_all(MUSL_RUNTIME_BYTES)?;
        file.set_permissions(fs::Permissions::from_mode(0o754))?;
        drop(file);
        fs::rename(&tmp, target)
    })();

    match result {
        Ok(()) => debug!("Wrote musl runtime file: {target}"),
        Err(e) => {
            let _ = fs::remove_file(&tmp);
            debug!("Failed to extract burrito_ng musl runtime: {e}");
        }
    }
}
